// <diletta-data-row> — a INSTÂNCIA WEB de `design-system-data-row`.
//
// A tarja é DELA e não da célula: quem sabe o estado da linha inteira é a linha.
// Se a tarja morasse na célula, a primeira coluna teria um conhecimento que as
// outras seis não têm — a mesma regra que faz o separador ser do DilettaAppList.
import './diletta-data-cell.js';

const ESTADO = { aviso: 'warning', erro: 'error', sucesso: 'success' };
// O PORTE decide a MOLDURA, não só a altura. A primeira versão media só a altura e
// errou por isso: as de 64 andam de 64 em 64 no arquivo — encostadas, separadas por
// régua e SEM tarja. Linha que encosta não é cartão.
const PORTE = {
  tabela: { altura: 54, cartao: true },
  painel: { altura: 52, cartao: true },
  historico: { altura: 64, cartao: false },
};
// A coluna de seleção existe no arquivo, com 28, e está OCULTA em 125 instâncias.
const SELECAO = 28;

class DilettaDataRow extends HTMLElement {
  static observedAttributes = ['estado', 'porte', 'selecao', 'href'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  get porte() {
    const v = this.getAttribute('porte');
    return PORTE[v] ? v : 'tabela';
  }

  get selecionavel() { return this.getAttribute('selecao') === 'caixa'; }

  render() {
    // Sem default no eixo Estado: linha neutra não apareceu em nenhuma das
    // instâncias medidas, e inventar um default seria escolher o caso mais comum
    // de uma tabela sem ter medido nenhum. Sem estado, sem tarja.
    const papel = ESTADO[this.getAttribute('estado')];
    const porte = this.porte;
    const { altura, cartao } = PORTE[porte];
    // A tarja só existe em moldura de cartão: no porte encostado a régua da
    // coleção já separa, e uma faixa colorida numa linha sem canto arredondado
    // desenharia um retângulo colado no vizinho.
    const tarja = cartao && papel;

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        .linha {
          box-sizing: border-box;
          height: ${altura}px;
          display: flex; align-items: center; gap: 16px;
          padding: 0 ${cartao ? 16 : 0}px;
          background: ${cartao ? 'var(--cps-surface)' : 'transparent'};
          border-radius: ${cartao ? 8 : 0}px;
          position: relative;
          /* A tarja é uma FAIXA e não uma borda: os papéis dela são da família
             Surface/Feedback, e borda esquerda de 4px arredondaria errado no
             canto. */
          /* O traço EXTERNO: 1px em todo o contorno, e o papel é borderSubtle —
             medido em #ececec, que é o neutral09 que esse papel aliasa. O border
             é um degrau mais escuro e engrossaria uma grade de vinte linhas. */
          border-width: ${cartao ? 1 : 0}px; border-style: solid;
          border-color: ${cartao ? 'var(--cps-borderSubtle)' : 'transparent'};
        }
        /* O parágrafo do porte histórico solta a altura da linha, e é a razão de
           ele ter 64 e não 54. */
        :host([porte="historico"]) .linha { height: auto; min-height: ${PORTE.historico.altura}px; }
        /* O SEGUNDO TRAÇO mora numa camada de DENTRO, e não é borda da linha.
           Medido no pixel: 3px de largura e 48 de altura numa linha de 54 — recuo
           de 3 em cada ponta, com 2px de superfície entre ele e o traço externo.
           Borda da linha iria de canto a canto e seguiria o arredondamento de
           fora; esta flutua dentro, com canto próprio. */
        .tarja {
          position: absolute; inset: 2px auto 2px 0;
          width: 3px; border-radius: 999px;
        }
        /* A coluna de SELEÇÃO abre 28 na borda inicial — o mesmo 28 que está
           construído e desligado em 125 instâncias do arquivo. */
        .selecao { width: ${SELECAO}px; flex: none; display: flex; justify-content: center; }
      </style>
      <div class="linha" part="linha" role="row"
           ${papel ? `data-estado="${this.getAttribute('estado')}"` : ''}>
        ${tarja ? `<span class="tarja" aria-hidden="true"
             style="background: var(--cps-${papel})"></span>` : ''}
        ${this.selecionavel ? '<span class="selecao"><slot name="selecao"></slot></span>' : ''}
        <slot></slot>
      </div>`;
  }
}

customElements.define('diletta-data-row', DilettaDataRow);
export { DilettaDataRow, PORTE, ESTADO };
